	}
	if err := runner.WriteCatalog(path, catalog); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Printf("wrote %s with %d tasks\n", path, len(catalog.Tasks))
}

