			}
		}
	}

	if err := runner.WriteSummaries(outputDir); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if *mode == "pilot" {
		copySummary(outputDir, ".")
	}
